changeSet.sql:
CREATE UNIQUE INDEX ux_pen_assignment_open_per_cattle ON pen_assignment (cattle_id) WHERE to_date IS NULL;
CREATE UNIQUE INDEX ux_qr_tag_active_per_cattle ON cattle_qr_tag (cattle_id) WHERE status = 'ACTIVE';
CREATE UNIQUE INDEX ux_cattle_ear_tag_active ON cattle (farm_id, lower(ear_tag_number)) WHERE herd_status = 'ACTIVE' AND ear_tag_number IS NOT NULL;
CREATE UNIQUE INDEX ux_herd_entry_valid_per_cattle ON herd_entry (cattle_id) WHERE status = 'VALID';
CREATE UNIQUE INDEX ux_herd_exit_open_per_cattle ON herd_exit (cattle_id) WHERE status IN ('DRAFT','PENDING','CONFIRMED');
CREATE UNIQUE INDEX ux_herd_entry_calf_outcome ON herd_entry (calf_outcome_id) WHERE calf_outcome_id IS NOT NULL AND status <> 'VOID';
CREATE UNIQUE INDEX ux_trading_partner_name ON trading_partner (farm_id, lower(name));

CREATE EXTENSION IF NOT EXISTS btree_gist;
ALTER TABLE pen_assignment ADD CONSTRAINT ex_assignment_no_overlap
    EXCLUDE USING gist (cattle_id WITH =, daterange(from_date, to_date, '[)') WITH &&);

CREATE OR REPLACE FUNCTION fn_pen_capacity_guard() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE cap int; cnt int;
BEGIN
  IF NEW.to_date IS NOT NULL THEN RETURN NEW; END IF;
  SELECT capacity INTO cap FROM pen WHERE id = NEW.pen_id FOR UPDATE;
  SELECT count(*) INTO cnt FROM pen_assignment WHERE pen_id = NEW.pen_id AND to_date IS NULL AND id <> NEW.id;
  IF cnt + 1 > cap THEN
    RAISE EXCEPTION 'Pen is full (% / %) (BR-D09)', cnt, cap USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END $$;

ALTER TABLE pen ADD CONSTRAINT ck_pen_capacity CHECK (capacity BETWEEN 1 AND 9999) NOT VALID;
ALTER TABLE pen ADD CONSTRAINT ck_pen_code CHECK (code ~ '^[A-Za-z0-9-]{1,20}$') NOT VALID;
ALTER TABLE pen_criteria_version ADD CONSTRAINT ck_pen_criteria_age CHECK (min_age_months IS NULL OR min_age_months BETWEEN 0 AND 240);
ALTER TABLE pen_criteria_version ADD CONSTRAINT ck_pen_criteria_weight CHECK (min_weight_kg IS NULL OR min_weight_kg BETWEEN 1 AND 1500);
ALTER TABLE pen_assignment ADD CONSTRAINT ck_assignment_dates CHECK (to_date IS NULL OR to_date >= from_date);
ALTER TABLE cattle ADD CONSTRAINT ck_cattle_exit CHECK ((herd_status = 'EXITED') = (exit_type IS NOT NULL AND exit_date IS NOT NULL)) NOT VALID;
ALTER TABLE cattle ADD CONSTRAINT ck_cattle_void CHECK (herd_status <> 'VOIDED' OR void_reason IS NOT NULL) NOT VALID;
ALTER TABLE cattle ADD CONSTRAINT ck_cattle_parent CHECK (dam_id IS DISTINCT FROM id AND sire_id IS DISTINCT FROM id) NOT VALID;
ALTER TABLE cattle ADD CONSTRAINT ck_cattle_sire CHECK (sire_id IS NULL OR external_sire_code IS NULL) NOT VALID;
ALTER TABLE trading_partner ADD CONSTRAINT ck_partner_has_role CHECK (is_seller OR is_buyer OR is_supplier);
ALTER TABLE herd_entry_voucher ADD CONSTRAINT ck_entry_amounts CHECK (cattle_amount >= 0 AND transport_fee >= 0 AND amount_paid >= 0);
ALTER TABLE herd_entry_voucher ADD CONSTRAINT ck_entry_purchase_seller CHECK (entry_type <> 'PURCHASE' OR seller_id IS NOT NULL OR status = 'DRAFT');
ALTER TABLE herd_entry_voucher ADD CONSTRAINT ck_entry_farm_born_no_amount CHECK (entry_type <> 'FARM_BORN' OR (cattle_amount = 0 AND transport_fee = 0 AND seller_id IS NULL));
ALTER TABLE herd_entry_voucher ADD CONSTRAINT ck_entry_voided CHECK (status <> 'VOIDED' OR (void_reason IS NOT NULL AND voided_at IS NOT NULL));
ALTER TABLE herd_exit_voucher ADD CONSTRAINT ck_exit_death CHECK (exit_type <> 'DEATH' OR (cattle_amount = 0 AND deductions = 0));
ALTER TABLE herd_exit_voucher ADD CONSTRAINT ck_exit_closed CHECK (status NOT IN ('DISMISSED','VOIDED') OR close_reason IS NOT NULL);
ALTER TABLE voucher_payment ADD CONSTRAINT ck_payment_amount CHECK (amount > 0);
ALTER TABLE voucher_payment ADD CONSTRAINT ck_payment_one_voucher CHECK (num_nonnulls(entry_voucher_id, exit_voucher_id) = 1);
ALTER TABLE voucher_payment ADD CONSTRAINT ck_payment_direction CHECK ((exit_voucher_id IS NOT NULL) = (direction = 'COLLECT'));
ALTER TABLE voucher_payment ADD CONSTRAINT ck_payment_void CHECK (status = 'RECORDED' OR void_reason IS NOT NULL);
ALTER TABLE herd_entry ADD CONSTRAINT ck_entry_cattle CHECK (status = 'DRAFT' OR cattle_id IS NOT NULL);
ALTER TABLE pre_entry_history_declaration ADD CONSTRAINT ck_declaration_items CHECK (status <> 'KNOWN' OR items IS NOT NULL OR category = 'REPRODUCTION');
